package com.example.rokidgeminisecretary;
import org.json.*;
public class TuningPhoneTest {static int n;static void ok(boolean yes){n++;if(!yes)throw new AssertionError("tuning "+n);}public static void main(String[] args)throws Exception{ok(VolumeProfilePolicy.level(50,10)==5);ok(VolumeProfilePolicy.level(110,10)==10);ok(VolumeProfilePolicy.level(-1,10)==0);ok(VolumeProfilePolicy.mode(true,true).equals("meeting"));ok(VolumeProfilePolicy.mode(false,true).equals("navigation"));ok(!VolumeProfilePolicy.mayRestore(4,3));ok(VolumeProfilePolicy.mayRestore(3,3));JSONArray a=MeetingActionPolicy.candidates("# 要点\n通常の説明です\n# 次の作業\n- 佐藤が確認する。期限は未定。\n- 見積もりを比較する。\n# 決定事項\n資料を採用しました");ok(a.length()==2);ok(a.getJSONObject(0).getString("text").contains("期限は未定"));ok(!a.toString().contains("資料を採用"));ok(MeetingActionPolicy.candidates("ただの説明。日程なし。").length()==0);ok(MeetingActionPolicy.candidates("担当者が確認する\n担当者が確認する").length()==1);StringBuilder many=new StringBuilder("# TODO\n");for(int i=0;i<30;i++)many.append("確認する ").append(i).append("\n");ok(MeetingActionPolicy.candidates(many.toString()).length()==12);System.out.println("PASS tuning phone "+n);}}
